<?php
require_once '../includes/auth.php';requireActiveUser();requireTenantContext();requireModulePermission('payments','view');
global $conn;$tenantId=(int)getCurrentTenantId();$rows=[];$q=$conn->prepare("SELECT * FROM failed_mpesa_transactions WHERE tenant_id=? ORDER BY id DESC LIMIT 300");if($q){$q->bind_param('i',$tenantId);$q->execute();$z=$q->get_result();while($r=$z->fetch_assoc())$rows[]=$r;$q->close();}
$pageTitle='Failed M-Pesa';require_once '../includes/header.php';?><div class="dashboard-card"><div class="page-header"><div><h2>Failed M-Pesa Transactions</h2><p>Review failed collections, reasons and retry status.</p></div></div><div class="table-responsive"><table><thead><tr><th>Phone</th><th>Amount</th><th>Reference</th><th>Failure</th><th>Retry</th><th>Created</th></tr></thead><tbody><?php foreach($rows as $x):?><tr><td><?=e($x['phone_number']??'—')?></td><td><?=e(formatMoney($x['amount']))?></td><td><?=e($x['account_reference']??'—')?></td><td><?=e($x['failure_reason']??$x['failure_code']??'—')?></td><td><?=e($x['retry_status'])?></td><td><?=e($x['created_at'])?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6">No failed M-Pesa transactions recorded.</td></tr><?php endif;?></tbody></table></div></div><?php require_once '../includes/footer.php';?>